package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"testing"
)

const testVariantPTX = `//
// Generated by NVIDIA NVVM Compiler
//
.version 8.8
.target sm_121a
.visible .entry ds4_rms(
	.param .u64 x
)
{
	.reg .f32 %f<4>;
	ld.param.u64 	%rd1, [x];
	div.rn.f32 	%f1, %f2, %f3;
	@%p1 bra 	$L__BB0_2;
	sqrt.rn.f32 	%f2, %f1;
$L__BB0_2:
	ret;
}
`

const testVariantSASS = `	Function : ds4_rms
/*0000*/                   LDG.E R0, [R2.64] ;
/*0010*/                   MUFU.RCP R3, R0 ;
/*0020*/                   FCHK P0, R0, R1 ;
/*0030*/                   RET ;
`

func TestCountPTXOpcodes(t *testing.T) {
	got := countPTXOpcodes(testVariantPTX)
	want := map[string]int{
		"ld.param.u64": 1,
		"div.rn.f32":   1,
		"bra":          1,
		"sqrt.rn.f32":  1,
		"ret":          1,
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("countPTXOpcodes() = %v, want %v", got, want)
	}
}

func TestCountSASSOpcodes(t *testing.T) {
	opcodes, kernels := countSASSOpcodes(testVariantSASS)
	if opcodes["MUFU.RCP"] != 1 || opcodes["FCHK"] != 1 {
		t.Errorf("countSASSOpcodes() opcodes = %v, want MUFU.RCP and FCHK", opcodes)
	}
	if kernels["ds4_rms"] != 4 {
		t.Errorf("countSASSOpcodes() kernels = %v, want ds4_rms: 4", kernels)
	}
	if opcodes, kernels := countSASSOpcodes(""); len(opcodes) != 0 || len(kernels) != 0 {
		t.Errorf("countSASSOpcodes(\"\") = %v, %v, want empty", opcodes, kernels)
	}
}

func TestParseVariantOptions(t *testing.T) {
	tests := []struct {
		name      string
		in        string
		want      []string
		recompile bool
	}{
		{"empty", "  ", nil, false},
		{"capture", "capture", nil, false},
		{"one", "--use_fast_math", []string{"--use_fast_math"}, true},
		{"several", " --gpu-architecture=sm_121a  --use_fast_math ", []string{"--gpu-architecture=sm_121a", "--use_fast_math"}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, recompile := parseVariantOptions(tt.in)
			if !reflect.DeepEqual(got, tt.want) || recompile != tt.recompile {
				t.Errorf("parseVariantOptions(%q) = %v, %v, want %v, %v", tt.in, got, recompile, tt.want, tt.recompile)
			}
		})
	}
}

func TestDiffVariants(t *testing.T) {
	a := &nvrtcVariant{Label: "capture", Stats: variantStats{
		PTXInstructions:  10,
		SASSInstructions: 100,
		Kernels:          map[string]int{"ds4_rms": 60, "ds4_hc_post": 40},
		SASSOpcodes:      map[string]int{"FCHK": 12, "MUFU.RCP": 8, "FFMA": 30},
	}}
	b := &nvrtcVariant{Label: "--use_fast_math", Stats: variantStats{
		PTXInstructions:  9,
		SASSInstructions: 70,
		Kernels:          map[string]int{"ds4_rms": 30, "ds4_hc_post": 40},
		SASSOpcodes:      map[string]int{"FCHK": 0, "MUFU.RCP": 6, "FFMA": 30},
	}}

	got := diffVariants(a, b)
	want := []variantDelta{
		{Group: "total", Name: "PTX instructions", A: 10, B: 9, Delta: -1},
		{Group: "total", Name: "SASS instructions", A: 100, B: 70, Delta: -30},
		{Group: "kernel", Name: "ds4_rms", A: 60, B: 30, Delta: -30},
		{Group: "sass", Name: "FCHK", A: 12, B: 0, Delta: -12},
		{Group: "sass", Name: "MUFU.RCP", A: 8, B: 6, Delta: -2},
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("diffVariants() = %+v, want %+v", got, want)
	}
	if diffVariants(nil, b) != nil {
		t.Error("diffVariants(nil, b) = non-nil, want nil")
	}
}

func TestNewVariantStats(t *testing.T) {
	s := newVariantStats(testVariantPTX, testVariantSASS)
	if s.PTXInstructions != 5 {
		t.Errorf("PTXInstructions = %d, want 5", s.PTXInstructions)
	}
	if s.SASSInstructions != 4 {
		t.Errorf("SASSInstructions = %d, want 4", s.SASSInstructions)
	}
	if s.Kernels["ds4_rms"] != 4 {
		t.Errorf("Kernels = %v, want ds4_rms: 4", s.Kernels)
	}
}

func TestRecompileHandler(t *testing.T) {
	src := &recompileSource{
		File:    "ds4_math.cu",
		Arch:    "sm_121a",
		Options: []string{"--gpu-architecture=sm_121a", "--generate-line-info"},
		Source:  "extern \"C\" __global__ void ds4_rms(float *x) {}",
		PTX:     testVariantPTX,
		SASS:    testVariantSASS,
	}
	var gotOptions []string
	compile := func(name, source string, options []string) *nvrtcVariant {
		gotOptions = options
		if name != src.File || source != src.Source {
			t.Errorf("compile(%q, %q, ...), want (%q, %q)", name, source, src.File, src.Source)
		}
		// One MUFU.RCP fewer and no FCHK, as fast math removes the check.
		return &nvrtcVariant{
			Label:   strings.Join(options, " "),
			Options: options,
			SASS:    "\tFunction : ds4_rms\n/*0000*/ LDG.E R0, [R2.64] ;\n/*0010*/ MUFU.RCP R3, R0 ;\n/*0020*/ RET ;\n",
			Stats:   newVariantStats("", "\tFunction : ds4_rms\n/*0000*/ LDG.E R0, [R2.64] ;\n/*0010*/ MUFU.RCP R3, R0 ;\n/*0020*/ RET ;\n"),
		}
	}

	handler := newRecompileHandler(src, compile)
	req := httptest.NewRequest("GET", "/api/recompile?a=capture&b=--gpu-architecture%3Dsm_121a+--use_fast_math", nil)
	rec := httptest.NewRecorder()
	handler(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d: %s", rec.Code, http.StatusOK, rec.Body.String())
	}
	var resp recompileResponse
	if err := json.NewDecoder(rec.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if want := []string{"--gpu-architecture=sm_121a", "--use_fast_math"}; !reflect.DeepEqual(gotOptions, want) {
		t.Errorf("compiled with %v, want %v", gotOptions, want)
	}
	if resp.A.Label != captureVariantLabel || resp.A.Stats.SASSInstructions != 4 {
		t.Errorf("A = %+v, want the capture's own artifacts", resp.A)
	}
	if resp.B.Stats.SASSInstructions != 3 {
		t.Errorf("B SASS instructions = %d, want 3", resp.B.Stats.SASSInstructions)
	}
	if resp.Caveat == "" {
		t.Error("response carries no static-count caveat")
	}
	var fchk bool
	for _, d := range resp.Deltas {
		if d.Group == "sass" && d.Name == "FCHK" {
			fchk = true
			if d.A != 1 || d.B != 0 || d.Delta != -1 {
				t.Errorf("FCHK row = %+v, want 1 -> 0", d)
			}
		}
	}
	if !fchk {
		t.Error("deltas report no FCHK change")
	}
}

func TestPipelineServerServesNVRTCPanel(t *testing.T) {
	cap, _ := createTest5TierCapture(t)
	data, err := buildPipelineViewData(cap, "capture.pprof", "")
	if err != nil {
		t.Fatalf("buildPipelineViewData: %v", err)
	}
	if data.Recompile == nil || data.Recompile.Source == "" {
		t.Fatal("capture with CUDA C++ source produced no recompile source")
	}
	if want := []string{"--gpu-architecture=sm_121a", "--generate-line-info", "--use_fast_math"}; !reflect.DeepEqual(data.Recompile.Suggested, want) {
		t.Errorf("Suggested = %v, want %v", data.Recompile.Suggested, want)
	}

	handler := newPipelineServerHandler(data)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/", nil))
	if !strings.Contains(rec.Body.String(), "nvrtcPanel") || !strings.Contains(rec.Body.String(), "--use_fast_math") {
		t.Error("served page offers no NVRTC flag panel")
	}

	// Both sides name the capture, so the route answers without compiling.
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/api/recompile?a=capture&b=capture", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("/api/recompile status = %d, want %d: %s", rec.Code, http.StatusOK, rec.Body.String())
	}
	var resp recompileResponse
	if err := json.NewDecoder(rec.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if len(resp.Deltas) != 2 || resp.Deltas[0].Delta != 0 || resp.Deltas[1].Delta != 0 {
		t.Errorf("capture compared against itself reports %+v, want zero deltas", resp.Deltas)
	}
}

func TestRecompileHandlerWithoutSource(t *testing.T) {
	handler := newRecompileHandler(&recompileSource{File: "kernels.cu"}, func(string, string, []string) *nvrtcVariant {
		t.Error("compiled a capture that retained no source")
		return nil
	})
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/api/recompile?a=capture&b=--use_fast_math", nil))
	if rec.Code != http.StatusNotFound {
		t.Errorf("status = %d, want %d", rec.Code, http.StatusNotFound)
	}
}

func TestDefaultRecompileOptions(t *testing.T) {
	if got, want := defaultRecompileOptions("sm_121a"), []string{"--gpu-architecture=sm_121a", "--generate-line-info"}; !reflect.DeepEqual(got, want) {
		t.Errorf("defaultRecompileOptions(sm_121a) = %v, want %v", got, want)
	}
	if got, want := defaultRecompileOptions(""), []string{"--generate-line-info"}; !reflect.DeepEqual(got, want) {
		t.Errorf("defaultRecompileOptions(\"\") = %v, want %v", got, want)
	}
}
